import{_ as a,H as t,f as i,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"14-Web3.0正在形成的合力","description":"","frontmatter":{},"headers":[{"level":2,"title":"各国政府对 Web 3.0 的基本态度","slug":"各国政府对-web-3-0-的基本态度","link":"#各国政府对-web-3-0-的基本态度","children":[{"level":3,"title":"美国政府的做法","slug":"美国政府的做法","link":"#美国政府的做法","children":[]},{"level":3,"title":"日本、新加坡以及其他各国政府的做法","slug":"日本、新加坡以及其他各国政府的做法","link":"#日本、新加坡以及其他各国政府的做法","children":[]}]},{"level":2,"title":"互联网公司对 Web 3.0 的基本态度和采取的行动","slug":"互联网公司对-web-3-0-的基本态度和采取的行动","link":"#互联网公司对-web-3-0-的基本态度和采取的行动","children":[{"level":3,"title":"以 Facebook 为代表的元宇宙路线","slug":"以-facebook-为代表的元宇宙路线","link":"#以-facebook-为代表的元宇宙路线","children":[]},{"level":3,"title":"以谷歌为代表的基础设施路线","slug":"以谷歌为代表的基础设施路线","link":"#以谷歌为代表的基础设施路线","children":[]}]},{"level":2,"title":"Web 3.0 在部分领域形成的热点效应","slug":"web-3-0-在部分领域形成的热点效应","link":"#web-3-0-在部分领域形成的热点效应","children":[]},{"level":2,"title":"风险投资基金","slug":"风险投资基金","link":"#风险投资基金","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web3.0入局攻略/14-Web3.0正在形成的合力.md","filePath":"Web3.0入局攻略/14-Web3.0正在形成的合力.md","lastUpdated":1795535932000}'),l={name:"Web3.0入局攻略/14-Web3.0正在形成的合力.md"};function b(o,e,r,n,s,h){return t(),i("div",null,[...e[0]||(e[0]=[p('<h1 id="_14-web3-0正在形成的合力" tabindex="-1">14-Web3.0正在形成的合力 <a class="header-anchor" href="#_14-web3-0正在形成的合力" aria-label="Permalink to &quot;14-Web3.0正在形成的合力&quot;">​</a></h1><p>你好，我是郭大治。</p><p>时间过得真快，从课程上线到现在差不多已经有 5 周的时间，课程也已经更新了 14 讲，但我们更新的速度，还是没有行业本身进展的速度那么快。比如我们在第 2 讲中提到的以太坊合并的内容，在一个多月之后，以太坊的合并已经近在眼前了。所以，在了解了 Web 3.0 各个领域的基本内容之后，接下来，我会再从宏观的视角给你做一些总体性的介绍，以便你可以更好地建立对于 Web 3.0 的理解框架。</p><p>今天这节课，我会从政府、互联网公司和风险投资基金讲起，让你知道在面对 Web 3.0 这一场已经开启的互联网革命的时候，我们应该要持有的基本态度和采取的主要行动。而在下节课，我们会站在行业和个人的角度，来谈谈如何把握新的机会。总之，希望能对你有些具体的帮助。</p><h2 id="各国政府对-web-3-0-的基本态度" tabindex="-1">各国政府对 Web 3.0 的基本态度 <a class="header-anchor" href="#各国政府对-web-3-0-的基本态度" aria-label="Permalink to &quot;各国政府对 Web 3.0 的基本态度&quot;">​</a></h2><p>在 Web 3.0 的实践方面，美国称得上是当前最为活跃的国家。不管是创业企业数量，还是融资规模，美国都居世界首位。而与此相对应，美国政府呢，也在 Web 3.0 领域采取了一种比较务实的态度。</p><h3 id="美国政府的做法" tabindex="-1">美国政府的做法 <a class="header-anchor" href="#美国政府的做法" aria-label="Permalink to &quot;美国政府的做法&quot;">​</a></h3><p>美国在联邦政府层面和州政府的层面，和业界建立了一种相对透明的沟通机制，向外界表明政府的关注。同时，他们也努力向外界说明，开展 Web 3.0 业务需要遵循的必要规则和监管适用框架。</p><p>在 2021 年 12 月 8 日，美国国会众议院金融服务委员会主席马克辛·沃特斯（Maxine Waters）和首席成员帕特里克·麦克亨利（Patrick Timothy McHenry），主持了一场题为“加密资产和金融的未来：了解美国金融创新的挑战和好处”听证会。麦克亨利在听证会上强调了一个观点，“Web 3.0 是下一代的互联网，未来的影响可能比互联网还大，应该如何确保 Web 3.0 革命发生在美国，让美国在这次竞赛中保持竞争力”，这个观点引起了参会者的普遍认同，这次听证会，也成为美国政界对于 Web 3.0 基本态度的首次公开表达。</p><p>然后，在 2022 年 3 月 9 日晚，美国总统拜登正式签署 14067 号《关于确保负责任地发展数字资产》的行政命令，该命令主要强调了围绕消费者和投资者保护、金融稳定、非法金融活动，其在全球金融系统及经济竞争中的领先地位、金融包容性以及负责任的创新等领域，美国政府应该采取的积极态度，并督促政府部门关注风险，积极探索和建立相关的监管政策。</p><p>接着，2022 年 6 月 7 日，美国共和党参议员辛西娅·鲁米斯（Cynthia Lummis）和民主党参议员科尔斯藤·吉利布兰德（Kristen Gillibrand），发起了一份跨党派提案《负责任的金融创新法案》（The Responsible Financial Innovation Act），希望针对 Web 3.0 监管中遇到一些具体问题，比如税收、证券属性、支付、银行、监管以及消费者保护等方面，提出具体的方案。</p><p>举例来说，在税收方面，提案希望针对个人以及 DAO，通过各种 Web 3.0 相关应用获得的收入，提出明确的税务征收和豁免的说明，比如在“挖矿”和“质押（Staking）”业务中，如果收益没有被处置，则不应被计入应税所得；而如果收益已经被处置，则应计入应税所得。</p><p>在借贷业务中，参照美国目前已有的证券借贷相关的规定，贷方获得的超过其自行持有的可获收益部分的超额收益，在处置之前不应计为应税收入，但在处置之后应被计为应税收入。</p><p>然后，因为“分叉”和“空投”获得的收入，应该被计为应税收入；因为“加密资产交易”发生的损失，则应计为个人收入；而去中心化自治组织（DAO），则应被接受为税法意义上的商业实体，相应地，其实现的一切收入，需要按照税法规定进行税务申报。</p><p>另外在州政府层面，2022 年 5 月 4 日，美国加州州长加文·纽森姆（Gavin ChristopherNewsom）签署了一项行政命令，强调加州将通过和美国联邦政府加强合作、为区块链应用创造机会以及加强消费者保护等方式，来促进加州为区块链创业公司提供一个公平、包容和利益均衡的商业环境。</p><p>而在加州之外，迈阿密对于 Web 3.0 的发展也非常积极，他们提出了一个把迈阿密建成 Web3.0 新硅谷的计划，迈阿密不仅每年一次举办 NFT 全球大会，还积极支持基于加密资产进行支付，甚至包括房产。迈阿密还成为了美国第一个将数字货币收益作为股息，发放给城市居民的城市，而市民需要通过去中心化钱包，来接收和使用这些资金。</p><h3 id="日本、新加坡以及其他各国政府的做法" tabindex="-1">日本、新加坡以及其他各国政府的做法 <a class="header-anchor" href="#日本、新加坡以及其他各国政府的做法" aria-label="Permalink to &quot;日本、新加坡以及其他各国政府的做法&quot;">​</a></h3><p>再说说日本政府，他们对于 Web 3.0 也表现出了非常明确的积极态度。</p><p>2022 年 6 月 7 日，日本政府批准了《2022 年经济财政运营和改革的基本方针》，该计划提出，日本将为建设一个去中心化数字世界，创造必要的环境。</p><p>而为了实现这一承诺，日本政府设立了专门的 Web 3.0 部长，发布了《NFT 白皮书》《关于在日本社会开放 Web 3.0 稳定币的提案》，以及世界上第一部关于稳定币的法案《资金决算法案修订案》，旨在为 Web 3.0 创业者提供指引，推动日本 Web 3.0 发展。</p><p>还有新加坡。新加坡一直以开放而积极的产业政策，以及透明和高效的营商环境而称著，对于Web 3.0 的态度也不例外。</p><p>新加坡已经建立起了一个包括会展、投资、孵化等多种业态在内的 Web 3.0 产业生态，新加坡最大的国企，也是最大的投资机构淡马锡，也多次出手，投资 Web 3.0 项目，包括专注于游戏领域的公链 Immutable、投资和行研机构 Amber Group，以及数字资产交易平台FTX.US。</p><p>另外就是欧盟，他们通过制定《加密资产市场条例》（MiCA），为 Web 3.0 涉及加密资产的相关业务提供指引。在这个条例中，主要是提出他们会严格监管加密资产交易所和稳定币，而对于 NFT、Pow 挖矿则不予监管，DeFi 暂时不予监管。但在 2023 年之后，欧盟会试点以嵌入式的方式来进行监管。</p><p>OK，我们再把目光转到阿联酋。2022 年 3 月，阿联酋的迪拜，设立了虚拟资产监管局（VARA），而且还通过了第一部关于加密资产交易的法律，规范了加密资产交易相关业务。迪拜希望通过立法，促进其成为全球加密资产市场的关键一环。</p><p>而且，阿联酋还通过设立免征所得税和公司税的特区，允许设立外资独资型加密资产公司，以及专门针对这一领域的孵化器，来吸引全球 Web 3.0 公司入驻。</p><p>最后是帕劳，他们推出了数字居民身份项目 RNS，为世界各地的人们提供加入帕劳体验 Web3.0 的机会，并且也允许加密资产交易平台在本地注册。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/1.png" alt=""></a></p><ul><li>图片来源于PANews</li></ul><p>所以，基于以上内容，我们能发现，多国政府不仅对于 Web 3.0 创意发展的意义有深度的认知，同时也在采取积极的行动，为 Web 3.0 的具体业务设置基本框架。不论是美国、欧洲，还是迪拜、帕劳等小型经济体，他们都在结合自己的资源情况，积极探索 Web 3.0 的应用落地。</p><h2 id="互联网公司对-web-3-0-的基本态度和采取的行动" tabindex="-1">互联网公司对 Web 3.0 的基本态度和采取的行动 <a class="header-anchor" href="#互联网公司对-web-3-0-的基本态度和采取的行动" aria-label="Permalink to &quot;互联网公司对 Web 3.0 的基本态度和采取的行动&quot;">​</a></h2><p>2022 年，新冠疫情在全球的肆虐进入第三年，虽然受疫情影响人们对线上场景的依赖进一步加强，但全球大型互联网公司的经营业绩，却难言乐观。</p><p>就拿 Facebook 的母公司 Meta 公布的 2022 年第一季财报来说，其总营收同比增加了 7%，但是净利润却同比下降 21%；谷歌母公司 Alphabet，在 2022 年第一季度的净利润，同比下滑 8%，虽然总营收增幅达 23%，但这已经是 2020 年以来的最低记录；还有微软发布 2022年财年第四季度财报，其第四财季营收统计增长 12%，净利润同比增长 2%。</p><p>其实，以上数字都说明了同一个问题，从移动互联网开始的一波红利已经遇到了天花板，考虑到各国政府针对数据泄露和数据滥用的监管力度，都在持续加强，那么以大型互联网公司为代表的消费互联网，实际上已经很难持续原来的高速增长了。</p><p>大型互联网公司要想在 Web 3.0 掀起的这场互联网革命中，找到自己的新的成长空间，首先需要的就是对于自己功能的重新定位。</p><p>那么，从目前大型互联网的实践来看，主要体现在了两个方向，一个是以 Facebook 为代表的元宇宙路线，另外一个是以谷歌为代表的基础设施路线。</p><h3 id="以-facebook-为代表的元宇宙路线" tabindex="-1">以 Facebook 为代表的元宇宙路线 <a class="header-anchor" href="#以-facebook-为代表的元宇宙路线" aria-label="Permalink to &quot;以 Facebook 为代表的元宇宙路线&quot;">​</a></h3><p>先说 Facebook，他们向元宇宙进发的决心和行动市场都是有目共睹的。</p><p>早在 2014 年，Facebook 就收购了 Oculous，并经过数年的连续投资，推出了在 VR 市场占据绝对优势的 Oculous Quest 系列成品。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/2.png" alt=""></a></p><ul><li>Oculous Quest 2</li></ul><p>然后在 2021 年 10 月，Facebook 更名 Meta，Oculous 产品线被整合为了 Reality Labs，专门负责元宇宙相关产品的研发。截至 2022 年第一季度，Reality Labs 已有员工近万名，已经占 Meta 全体员工总数的 20%，目前也已经推出了 Horizon Workroom 等产品（HorizonWorkroom 可以为用户提供一种虚拟和现实相混合的办公环境，用户可以将自己的办公桌、电脑等设备带到这个虚拟空间，并进行多人互动和会议）。</p><p>此外，Facebook 还积极推广稳定币项目，2019 年，他们就发布了 Libra 项目白皮书，计划为多国货币打造一个通用的稳定币的发行平台，后来项目方案几经修改，最终改名为 Diem 并上线，现在也已经可以在 Shopify、Uber 和 Sportify 等平台支付使用了。</p><h3 id="以谷歌为代表的基础设施路线" tabindex="-1">以谷歌为代表的基础设施路线 <a class="header-anchor" href="#以谷歌为代表的基础设施路线" aria-label="Permalink to &quot;以谷歌为代表的基础设施路线&quot;">​</a></h3><p>OK，然后我们再来看谷歌。</p><p>2022 年 5 月，谷歌组建一个 Web 3.0 团队，目标是为区块链开发人员提供后端服务。谷歌的Web 3.0 团队设置在了谷歌云旗下，这种组织架构的设计，显然就是希望谷歌云能在不断增长的区块链基础设施服务市场中，获得更大的份额。</p><p>那么，虽然说，区块链是以去中心化的节点为基本计算单元的，但是目前其实有相当多的节点，是运营在云计算平台上的，比如微软 2015 年在 Azure 云服务平台中，加入了 BaaS（Blockchain as a Service）服务，为企业客户、合作伙伴和开发人员，提供一键式基于云的区块链开发环境，让他们可以快速创建基于公有云、私有云以及混合云的区块链环境。</p><p>另外，亚马逊云也针对区块链节点运营服务，推出过专门的产品，并且已经在这一领域获得了比较大份额的市场。比如曾经有一次，亚马逊云宕机，就同时导致了 Coinbase 和 Binance 暂停服务。</p><p>所以说，以“自下而上”重构互联网为目的的 Web 3.0，对于中心化的基础设施服务既存在着一种心理上的排斥，又存在着一种事实上的依赖。谷歌正是瞄准了这一机会，为其正处于上升势头的云服务，增添了一份新的发展空间，毕竟谷歌云相对于亚马逊云和微软云来说，还处于明显的劣势。</p><p>而相对于谷歌和 Facebook，微软在 Web 3.0 领域的发力，更具有一种多元化的色彩。</p><p>微软早年就布局了去中心化身份认证，希望通过提供一种跨平台的、通用的数字身份，来为用户使用各种数字化应用提供便利，也希望能对用户产生一种新的粘性。</p><p>2021 年 4 月，Microsoft Azure Active Directory 可验证凭证的预览版上线，这个系统最大的特点，就在于可以给用户创造一种具有隐私保护功能，并且不受某一种应用限制的身份体系。</p><p>此外，微软在内容创作方面也频频出手，不仅在 2014 年收购了曾经占据游戏流量榜首的《我的世界》，还在 2022 年 1 月斥资 687 亿美元收购动视暴雪，从而为其游戏及内容层面增添了新的砝码。</p><h2 id="web-3-0-在部分领域形成的热点效应" tabindex="-1">Web 3.0 在部分领域形成的热点效应 <a class="header-anchor" href="#web-3-0-在部分领域形成的热点效应" aria-label="Permalink to &quot;Web 3.0 在部分领域形成的热点效应&quot;">​</a></h2><p>而在这些互联网巨头之外，Web 3.0 也正在某些领域，形成了非常明显的热点效应。</p><p>其一是支付。包括 Mastercard、Paypal 和 Square 在内的美国支付巨头都已入局，而且也推出了相应的产品开始抢占市场。</p><p>其中，Square 主打法币入金业务，通过支持多种法币买卖加密资产，这类业务的收入已经在Square 的总收入中占据了相当比例的份额；Paypal 是主动出击日本、英国等海外市场；而MasterCard 则推进到项目层面，通过接入 Immutable 等公链，为其应用生态提供支付服务。</p><p>其二是社交。一方面，Twitter、Instagram 等社交平台，都在纷纷测试 NFT 展示功能，使得用户通过这些已有账户，就可以展示自己的身份和个性。另一方面，不同的平台如 Instagram 和Facebook，也正在探讨用户数据的可迁移性，目标是用户可以把自己的社交关系，在不同的平台之间进行融合，从而使用户能够对自己的数据掌握主动权。</p><h2 id="风险投资基金" tabindex="-1">风险投资基金 <a class="header-anchor" href="#风险投资基金" aria-label="Permalink to &quot;风险投资基金&quot;">​</a></h2><p>不过，如果说大型互联网公司，对于 Web 3.0 还是在采取一种局部适应的态度的话，那么风险投资基金对于 Web 3.0 的态度，可谓是毫无保留地全面拥抱。作为最聪明、也是对趋势最敏感的资金，风险投资机构针对 Web 3.0 的投资规模在迅速加大，对于赛道选择也更加全面。</p><p>首先，我们可以根据 01 区块链、零壹智库《中国区块链产业发展普查报告（2021）》的数据来看。</p><p>2021 年，全球区块链产业一共发生了 1812 笔融资事件，其中 1433 笔披露金融的融资，涉及的金额总计达 486.74 亿美元，而这里面有 70% 的融资事件，是战略投资或种子 / 天使轮投资，14% 的融资事件为 A 轮，4% 的融资事件为 B 轮，其余都是并购。</p><p>我们从融资发生的地域来看，融资发生数量最多的国家是美国，在全球总体融资事件中，占比达 42.54%。其次是中国，占比为 8.33%，英国、加拿大发生的融资事件略少于中国，占比分别约为 8% 左右。</p><p>再从融资项目所在的细分赛道来看，加密资产交易相关项目占比最高，大约接近项目总数的30%。另外，NFT 相关、DeFi 和链游等赛道获得的融资，也比较可观，而分布式存储 / 计算、身份认证等赛道，则处于第三梯队。</p><p>事实上，进入 2022 年，虽然加密资产市场行情出现了比较大的回调，但风险投资基金对于Web 3.0 的热情依然不减。</p><p>根据 PANews 不完全统计，2022 年上半年，全球范围共推出了 107 支 Web 3.0 相关主题基金，总金额达 399 亿美元。其中，资金规模排在前三位的，分别是 Tiger Global 于 2 月推出的新基金 Private Investment Parters（110 亿美元）、a16z 的第四支加密货币基金 CryptoFund 4（45 亿美元），以及加密资产交易所 FTX 推出的风险投资基金（20 亿）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/14-Web3.0%25E6%25AD%25A3%25E5%259C%25A8%25E5%25BD%25A2%25E6%2588%2590%25E7%259A%2584%25E5%2590%2588%25E5%258A%259B/3.png" alt=""></a></p><ul><li>图片来源于PANews</li></ul><p>那么，我们从发起设立投资基金的机构类型来看，这 107 支基金，主要是由 6 类机构发起的，分别是传统风险投资机构、Crypto Fund（即加密行业原生的投资机构）、生态基金、加密资产交易所、Web 3.0 应用类项目以及其他机构。而其中，Crypto Fund、生态基金和传统风投机构，在基金数量上相对其他类型机构来说，都表现出了比较明显优势。</p><p>我们再从基金规模上看，仅传统风投机构，就占到了全部基金的一半以上，而且从基金的平均规模上来看，传统风投机构成立的基金，也还是占据了明显的优势，同时加密资产交易所成立的基金，也有一定的规模优势。</p><p>另外从基金公布的拟投资对象来看，基础设施、工具、元宇宙、NFT 及游戏，都是各基金相对聚焦的投资领域，而 DeFi、DAO 和中心化交易所则涉及得比较少。当然，也还有专门针对链游和基础设施的专项基金。</p><p>所以可见，对于风险投资基金来说，就算是处于市场比较低迷的状态下，其对于融资金额也还是保持在了比较高的水平上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们主要介绍了各国政府对于“确保 Web 3.0 首先发生在本国”的基本态度，同时也了解了大型互联网公司，在 Web 3.0 基础设施和应用方面的探索。另外，风险投资基金作为推动 Web 3.0 发展的重要力量，即使在市场低迷的上半年，其融资金额仍然保持在较高的水平。</p><p>可见，作为世界上对趋势最敏感，也是最聪明的几类机构，他们已经用实际行动，表明了自己对于 Web 3.0 的基本态度。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>除了政府、互联网公司和风险投资基金之外，你认为还有哪类机构对于 Web 3.0 的发展感兴趣？他们的出发点是什么呢？</p><p>欢迎在评论区留言，分享你的看法。另外，也欢迎你把今天的内容分享给更多的朋友。</p>',77)])])}const W=a(l,[["render",b]]);export{u as __pageData,W as default};
